    for r, c in singleton:
        neighbors = {}
        for x in range(max(0, r - 1), min(h, r + 2)):
            for y in range(max(0, c - 1), min(w, c + 2)):
                if (x, y) != (r, c) and (x, y) not in singleton:
                    neighbors[(x, y)] = g[x][y]
        # A speck may interrupt a 2x2 patch. Restore an unambiguous 2x2 fill first.
        square_scores = {}
        for x in (r - 1, r):
            for y in (c - 1, c):
                if 0 <= x < h - 1 and 0 <= y < w - 1:
                    cells = [(x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)]
                    vals = [g[a][b] for a, b in cells if (a, b) != (r, c) and (a, b) not in singleton]
                    counts = Counter(vals)
                    for color, n in counts.items():
                        square_scores[color] = max(square_scores.get(color, 0), n)
        perfect = [color for color, n in square_scores.items() if n == 3]
        if len(perfect) == 1:
            out[r][c] = perfect[0]
            continue
        orth = Counter(g[x][y] for x, y in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                       if 0 <= x < h and 0 <= y < w and (x,y) not in singleton)
        if orth:
            best = max(orth.values())
            choices = [v for v,n in orth.items() if n == best]
            if len(choices) == 1:
                out[r][c] = choices[0]
                continue
        counts = Counter(neighbors.values())
        if counts:
            best = max(counts.values())
            choices = [v for v,n in counts.items() if n == best]
            if len(choices) == 1:
                out[r][c] = choices[0]
            else:
                # Favor the color of the nearest stable pattern cell.
                dists = {v: min(max(abs(x-r),abs(y-c)) for (x,y),col in neighbors.items() if col == v) for v in choices}
                out[r][c] = min(choices, key=lambda v:(dists[v], -sum(1 for z in g for q in z if q==v), v))
    return out

